import os
import six
from .exception import ToolLogParserException
from lxml import etree

if six.PY2:
    from StringIO import StringIO
else:
    from io import StringIO


class ToolLogParser(object):

    def __init__(self, filepath, filename='Tool.log'):
        with open(os.path.join(filepath, filename)) as tool_log:
            self.all_lines = tool_log.readlines()

    def request_should_be_sent_from_sem_to_bts(self, req_type, occurence):
        """Checks if request is sent to bts from SEM
        :param String req_type   The message sent
        :param String occurence  The originality of the req_type message sent. Defaults to 1 (1st instance of the req_type message)
        """
        return self._get_msg_seq_number(req_type, occurence)

    def all_responses_for_request_should_be(self, req_type, occurence, responses):
        """ Checks if all responses sent by BTS to the SEM is the set of messages defined
        :param String req_type   The message sent by BTS
        :param String occurence  The originality of the req_type message sent. Defaults to 1 (1st instance of the req_type message)
        :param List responses  list containing ALL responses sent by BTS to SEM
        """
        seq_number = self._get_msg_seq_number(req_type, occurence)
        lines = self._get_lines_containing(seq_number)

        is_response_available_list = []
        for line in lines[1:]:
            is_response_available_list.append(any(response in line for response in responses))

        if len(is_response_available_list) != len(responses):
            raise ToolLogParserException("Number of actual reponses received ({})does not match"
                                         "number of responses given ({}).".format((len(is_response_available_list)), (len(responses))))

    def a_response_for_request_should_be(self, req_type, occurence, response):
        """ Checks if the response is received by SEM
        :param String req_type    The message sent from SEM to BTS
        :param String occurence   The originality of the req_type message sent. Defaults to 1 (1st instance of the req_type message)
        :param String response    Response sen by BTS to SEM
        """
        seq_number = self._get_msg_seq_number(req_type, occurence)

        lines = self._get_lines_containing(seq_number)

        if not any(response in line for line in lines):
            raise ToolLogParserException("Response does not exist in log file.")

    def _get_lines_containing(self, message):
        return [line.strip() for line in self.all_lines if message in line]

    def _get_msg_seq_number(self, req_type, occurence=1):
        occurences = self._get_ocurrences(req_type)
        if occurence-1 < len(occurences):
            return self._get_seq_number(occurences, occurence-1)
        else:
            raise ToolLogParserException("Response does not exist in log file.")

    def _get_seq_number(self, lines, occurrence):
        xml_node = etree.parse(StringIO(lines[occurrence])).getroot()
        return next(iter(xml_node.findall("./*/_seqNumber")), None).text

    def _get_ocurrences(self, req_type):
        return [line.rsplit('<?xml version="1.0"?>')[1].split()[0] for line in self.all_lines if '[DEBUG] Sent' in line and req_type in line]
